"use client";

import { useState } from "react";
import { Dialog, DialogContent } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { createNewTask } from "@/app/actions/task-actions"; // Yeni eklediğimiz action

export default function TaskFormModal({ open, setOpen }: any) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [loading, setLoading] = useState(false);

  async function handleSubmit() {
    setLoading(true);
    const result = await createNewTask({
      task: title,
      description: description,
    });

    if (result.success) {
      setTitle("");
      setDescription("");
      setOpen(false); // Modalı kapat
    }
    setLoading(false);
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogContent className="bg-[#0E153A]/90 border border-teal-400/30 shadow-2xl backdrop-blur-xl p-6 rounded-2xl">
        <div className="mb-4">
          <h2 className="text-teal-300 text-2xl font-bold">Nieuwe Taak Aanmaken</h2>
        </div>

        <div className="flex flex-col gap-4 mt-4">
          <Input
            placeholder="Taak Titel"
            value={title}
            onChange={(e) => setTitle(e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />
          <Textarea
            placeholder="Beschrijving"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            className="bg-[#0b1233] text-teal-200 border-teal-400/30"
          />
          <Button
            onClick={handleSubmit}
            disabled={loading}
            className="bg-gradient-to-r from-teal-400 to-fuchsia-400 text-black font-bold shadow-lg mt-3 hover:scale-105 transition"
          >
            {loading ? "Opslaan..." : "Opslaan"}
          </Button>
        </div>
      </DialogContent>
    </Dialog>
  );
}