"use server";

import { prisma } from "@/src/lib/prisma";
import { revalidatePath } from "next/cache";

export async function createNewTask(formData: any) {
  try {
    await prisma.task.create({
      data: {
        title: formData.task,
        description: formData.description,
        status: "TODO", 
        priority: "MEDIUM",
        userId: "buraya-sabit-bir-user-id-veya-session-id-gelecek",
      },
    });

    revalidatePath("/");
    revalidatePath("/tasks");
    
    return { success: true };
  } catch (error) {
    console.error("Task Error:", error);
    return { success: false };
  }
}